import{_ as a,o as n,c as e,a2 as i}from"./chunks/framework.doxMM-x8.js";const k=JSON.parse('{"title":"安装固定场景并管理一次 Simulation Session","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/tutorials/simulation-session","contentType":"tutorial","prev":{"text":"合成运动与两个 Viewer","link":"/tutorials/synthetic-motion"},"next":{"text":"空间工作台","link":"/tutorials/spatial-workbench"}},"headers":[],"relativePath":"tutorials/simulation-session.md","filePath":"tutorials/simulation-session.md"}'),t={name:"tutorials/simulation-session.md"};function p(l,s,o,r,c,h){return n(),e("div",null,[...s[0]||(s[0]=[i(`<h1 id="安装固定场景并管理一次-simulation-session" tabindex="-1">安装固定场景并管理一次 Simulation Session <a class="header-anchor" href="#安装固定场景并管理一次-simulation-session" aria-label="Permalink to &quot;安装固定场景并管理一次 Simulation Session&quot;">​</a></h1><p>目标：显式运行一个固定场景，并在两个桌面 Viewer 中观察同一个 Simulation Session。每个 Viewer 保留各自的相机、选择和 Inspector。</p><p>先完成<a href="./persistent-world">持久 Lab 与对象</a>和<a href="./persistent-assets">持久数字资产</a>。使用仓库指定的 Node、pnpm、Python 3.10+、venv 和 pip，以及 Linux 或 WSL Ubuntu。从仓库根目录执行 Bash 命令。它们创建隔离的开发数据。本章使用开发合成运动，不需要 GPU、Newton 或 Docker。可靠 Lab Recording 仍是后续能力。</p><h2 id="配置由服务持有的来源" tabindex="-1">配置由服务持有的来源 <a class="header-anchor" href="#配置由服务持有的来源" aria-label="Permalink to &quot;配置由服务持有的来源&quot;">​</a></h2><p>用 Ctrl+C 停止你之前启动的开发实例。创建 Python 环境并启动应用：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .scratch/session-python</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.scratch/session-python/bin/python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/synthetic-motion/requirements.txt</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LAB_WORD_SYNTHETIC_SESSION</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LAB_WORD_SYNTHETIC_PYTHON</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/.scratch/session-python/bin/python&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LAB_WORD_DATA_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.scratch/session-tutorial-data</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>打开 <a href="http://127.0.0.1:5173/lab" target="_blank" rel="noreferrer">http://127.0.0.1:5173/lab</a>。注册或以普通 Member 登录。创建名为 <code>Shared Session</code> 的空 Lab。在资产库导入 <code>tests/fixtures/lab/cube.glb</code>，填写来源、许可与版本，再返回 Lab。安装选项来自已保存的资产库，不需要已有 Lab 对象。</p><p>普通 Node/Web 启动和构建不需要 Python。这个显式设置启用 loopback 开发来源。服务仅在 Start 后启动 Python。<a href="https://github.com/CaiZongyuan/labworld/blob/c80e63c8c063e44ca80c85970b518c35fb448c8e/apps/server/src/synthetic-source.ts" target="_blank" rel="noreferrer">来源监管器</a>持有进程、stdin 管道和清理 ledger。它只发送一次固定启动条件，并保持管道打开。不要手动运行 <code>publisher.py --startup-stdin</code>。独立的<a href="./synthetic-motion">合成 fixture 教程</a>仍使用自己的显式启动合同。</p><h2 id="安装并-start" tabindex="-1">安装并 Start <a class="header-anchor" href="#安装并-start" aria-label="Permalink to &quot;安装并 Start&quot;">​</a></h2><ol><li>打开<strong>仿真会话</strong>。</li><li>在 <strong>GLB 模型</strong>中选择导入的资产。 如果它在后续页，点击<strong>加载更多</strong>。列表读取失败时，点击<strong>重试 GLB 模型列表</strong>。</li><li>点击<strong>安装固定场景</strong>。</li><li>选择生成的<strong>场景安装</strong>，保留 <code>30 Hz</code>。</li><li>点击 <strong>Start</strong>。</li><li>等待<strong>正在运行</strong>和<strong>运动已连接</strong>，再关闭对话框。</li></ol><p>固定场景包为 <code>development-synthetic@1</code>。安装登记 20 个独立 Entity 与 Scene Node，以及六个 joint key。第二份 Installation 创建不同对象身份。本章不升级场景包，也不为机器人每根 link 创建业务 Entity。</p><p>Start 固定保存实际布局、Installation、资产、参数和初始状态。来源第一帧重现这个初始状态。<strong>正在启动</strong>表示服务仍在等待初始帧。服务分配机器身份、唯一 Publisher 租约和 epoch。Viewer 不能选择 epoch 或替换 Publisher。</p><p>在第二个浏览器标签页打开同一 Lab。Viewer 自动观察活动会话。打开<strong>仿真会话</strong>并选择 <code>15 Hz</code>。转动这个 Viewer 的相机，选择另一个 Entity。两个 Viewer 显示相同的会话 UUID 与来源状态；相机和 Inspector 选择各自独立。<strong>离开观察</strong>只关闭此 Viewer 的订阅。<strong>观察会话</strong>会获取新票据。<strong>关闭</strong>保留观察连接。</p><h2 id="pause-与-resume" tabindex="-1">Pause 与 Resume <a class="header-anchor" href="#pause-与-resume" aria-label="Permalink to &quot;Pause 与 Resume&quot;">​</a></h2><ol><li>在任一 Viewer 点击 <strong>Pause</strong>。</li><li>等待<strong>已暂停 · 仿真时间和位姿已冻结</strong>。</li><li>保持两个 Viewer 打开数秒，并在暂停期间打开第三个标签页。</li><li>确认三个 Viewer 显示相同的冻结位姿。</li><li>点击 <strong>Resume</strong>，等待<strong>正在运行</strong>。</li></ol><p><strong>正在暂停</strong>与<strong>正在恢复</strong>表示请求已受理，来源动作尚未完成。来源发送一个新的完整边界帧及关联回执。Pause 显示该精确边界，包括 <code>15 Hz</code> Viewer；它不会冻结较旧的插值位姿。仿真时钟保持固定，心跳继续。暂停期间晚加入的 Viewer 接收固定映射和完整缓存位姿。</p><p>Resume 排除暂停期间的真实时间。它的可信边界建立新的接收时钟片段。同一服务端 epoch 内 sequence 保持递增。Viewer 不跨暂停区间插值，也不以重复 WELCOME 重置缓冲。运动接收新鲜度、连接健康和会话生命周期分别表达。</p><h2 id="比较-reset-与下次-start" tabindex="-1">比较 Reset 与下次 Start <a class="header-anchor" href="#比较-reset-与下次-start" aria-label="Permalink to &quot;比较 Reset 与下次 Start&quot;">​</a></h2><ol><li>暂停会话，记下 UUID。</li><li>关闭对话框。选择一个安装对象，打开<strong>编辑布局</strong>。</li><li>修改 X Placement 和尺度，保存布局。</li><li>返回<strong>运行</strong>视图。当前会话仍使用原来的固定几何和位姿。</li><li>打开<strong>仿真会话</strong>，点击 <strong>Reset</strong>。</li><li>等待新会话运行。它的 UUID 改变，启动快照仍是原快照。</li><li>点击 <strong>Stop</strong>，等待<strong>已停止</strong>。Viewer 返回最新保存的布局。</li><li>点击 <strong>Start</strong>。这次普通 Start 使用刚保存的 Placement 和尺度。</li></ol><p>布局编辑器预览下次 Start。保存不改变活动仿真。Reset 结束并隔离旧会话，清空 Viewer 缓冲，再获取绑定新会话的票据和映射。它保留已保存的 Placement 与 Registered Location。活动 Installation 不能悄悄改变对象归属或资产绑定；被拒绝的结构编辑保持原状态。其他 Lab 对象与 Device Program Run 保留各自行为。Inspector 读取当前 Entity 事实。</p><h2 id="检查冲突与拒绝" tabindex="-1">检查冲突与拒绝 <a class="header-anchor" href="#检查冲突与拒绝" aria-label="Permalink to &quot;检查冲突与拒绝&quot;">​</a></h2><p>保持会话运行或暂停，停止其他标签页的控制操作。在已登录 Lab 页面的浏览器 Console 中列出 Lab UUID：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> fetch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/api/v1/lab/labs&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">json</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()).data.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">map</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(({ </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  id,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  name,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}));</span></span></code></pre></div><p>把下面的完整函数粘贴到 Console。然后以 <code>Shared Session</code> 的 UUID 调用 <code>await checkSessionRefusals(&#39;&lt;lab-uuid&gt;&#39;)</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Paste into the Console of the authenticated, same-origin Lab page.</span></span>
<span class="line"><span>// Call with a Lab UUID whose Session is running or paused. Neither action is accepted.</span></span>
<span class="line"><span>globalThis.checkSessionRefusals = async function checkSessionRefusals(labId) {</span></span>
<span class="line"><span>  const read = async () =&gt; {</span></span>
<span class="line"><span>    const response = await fetch(\`/api/v1/lab/labs/\${labId}/sessions\`);</span></span>
<span class="line"><span>    if (!response.ok)</span></span>
<span class="line"><span>      throw new Error(\`Session list failed: \${response.status}\`);</span></span>
<span class="line"><span>    const page = await response.json();</span></span>
<span class="line"><span>    return page.data.find((session) =&gt; session.id === page.active_session_id);</span></span>
<span class="line"><span>  };</span></span>
<span class="line"><span>  const before = await read();</span></span>
<span class="line"><span>  if (</span></span>
<span class="line"><span>    !before ||</span></span>
<span class="line"><span>    ![&#39;running&#39;, &#39;paused&#39;].includes(before.status) ||</span></span>
<span class="line"><span>    before.revision &lt; 1</span></span>
<span class="line"><span>  )</span></span>
<span class="line"><span>    throw new Error(</span></span>
<span class="line"><span>      &#39;Start or Pause a Session, wait for its final state, then retry.&#39;,</span></span>
<span class="line"><span>    );</span></span>
<span class="line"><span>  const identityResponse = await fetch(&#39;/api/v1/auth/session&#39;);</span></span>
<span class="line"><span>  if (!identityResponse.ok) throw new Error(&#39;Sign in before this check.&#39;);</span></span>
<span class="line"><span>  const identity = await identityResponse.json();</span></span>
<span class="line"><span>  const action = before.status === &#39;paused&#39; ? &#39;resume&#39; : &#39;pause&#39;;</span></span>
<span class="line"><span>  const path = \`/api/v1/lab/labs/\${labId}/sessions/\${before.id}/\${action}\`;</span></span>
<span class="line"><span>  const conflict = await fetch(path, {</span></span>
<span class="line"><span>    method: &#39;POST&#39;,</span></span>
<span class="line"><span>    headers: {</span></span>
<span class="line"><span>      &#39;content-type&#39;: &#39;application/json&#39;,</span></span>
<span class="line"><span>      &#39;x-csrf-token&#39;: identity.csrf_token,</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>    body: JSON.stringify({ expected_revision: before.revision - 1 }),</span></span>
<span class="line"><span>  });</span></span>
<span class="line"><span>  if (conflict.status !== 409)</span></span>
<span class="line"><span>    throw new Error(\`Expected conflict 409, received \${conflict.status}\`);</span></span>
<span class="line"><span>  const denied = await fetch(path, {</span></span>
<span class="line"><span>    method: &#39;POST&#39;,</span></span>
<span class="line"><span>    headers: { &#39;content-type&#39;: &#39;application/json&#39; },</span></span>
<span class="line"><span>    body: JSON.stringify({ expected_revision: before.revision }),</span></span>
<span class="line"><span>  });</span></span>
<span class="line"><span>  if (denied.status !== 403)</span></span>
<span class="line"><span>    throw new Error(\`Expected CSRF refusal 403, received \${denied.status}\`);</span></span>
<span class="line"><span>  const after = await read();</span></span>
<span class="line"><span>  if (</span></span>
<span class="line"><span>    after?.id !== before.id ||</span></span>
<span class="line"><span>    after.revision !== before.revision ||</span></span>
<span class="line"><span>    after.status !== before.status</span></span>
<span class="line"><span>  )</span></span>
<span class="line"><span>    throw new Error(</span></span>
<span class="line"><span>      &#39;Session changed during the check. Stop other controls and retry.&#39;,</span></span>
<span class="line"><span>    );</span></span>
<span class="line"><span>  console.log({</span></span>
<span class="line"><span>    conflict: conflict.status,</span></span>
<span class="line"><span>    denied: denied.status,</span></span>
<span class="line"><span>    unchanged: true,</span></span>
<span class="line"><span>    session_id: after.id,</span></span>
<span class="line"><span>  });</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>预期输出为 <code>{ conflict: 409, denied: 403, unchanged: true, session_id: ... }</code>。第一个请求使用过期 revision。第二个请求省略 CSRF。两个请求都不改变会话。浏览器与有效的 <code>lab:full</code> Agent 使用同一 Lab 权限合同。Core 机器凭据独立，仅能使用专属的会话准入合同。</p><p>对话框表达冲突、访问拒绝、来源不可用和离线状态，并保留选择。<strong>重试</strong>读取当前权威状态并重新连接观察；它不重放 Start、Reset 或其他已受理动作。</p><h2 id="中断与结束" tabindex="-1">中断与结束 <a class="header-anchor" href="#中断与结束" aria-label="Permalink to &quot;中断与结束&quot;">​</a></h2><p>在会话运行期间用 Ctrl+C 停止 <code>pnpm dev</code>。使用同一命令和数据目录重新启动。之前的会话显示<strong>会话已中断</strong>。显式 Start 新会话。重启不会恢复旧实验或重放动作。</p><p>如果 Python 不可用，Start 报告来源失败或中断会话。检查配置的可执行文件，重新启动服务，再重试。服务使用有限的回执与运动失联期限。回执缺失、心跳丢失或运行来源停滞都会停止会话。主动 Pause 不参加运行来源进度检查。</p><p>结束时 Stop 会话、关闭对话框，再停止 <code>pnpm dev</code>。监管器释放自己持有的来源进程与 socket。ledger 保留在 <code>.scratch/session-tutorial-data/runtime/synthetic-sources/</code>。按需要保留教程数据目录和 Python 环境。不要移除其他 worktree 的进程或数据。</p><p>来源：<a href="https://github.com/CaiZongyuan/labworld/blob/c80e63c8c063e44ca80c85970b518c35fb448c8e/packages/server/src/lab/sessions/service.ts" target="_blank" rel="noreferrer">会话 owner</a>、<a href="https://github.com/CaiZongyuan/labworld/blob/c80e63c8c063e44ca80c85970b518c35fb448c8e/packages/server/src/lab/sessions/routes.ts" target="_blank" rel="noreferrer">HTTP 路由</a>、<a href="https://github.com/CaiZongyuan/labworld/blob/c80e63c8c063e44ca80c85970b518c35fb448c8e/packages/sdk/src/simulation-session.ts" target="_blank" rel="noreferrer">SDK 生命周期流</a>、<a href="https://github.com/CaiZongyuan/labworld/blob/c80e63c8c063e44ca80c85970b518c35fb448c8e/packages/views/src/lab/simulation-session-controls.tsx" target="_blank" rel="noreferrer">会话控件</a>、<a href="https://github.com/CaiZongyuan/labworld/blob/c80e63c8c063e44ca80c85970b518c35fb448c8e/packages/sdk/src/motion-buffer.ts" target="_blank" rel="noreferrer">运动缓冲</a>与 <a href="https://github.com/CaiZongyuan/labworld/blob/c80e63c8c063e44ca80c85970b518c35fb448c8e/packages/views/src/lab/motion-scene.ts" target="_blank" rel="noreferrer">body 到可视目标校正</a>。来源参数默认 translation amplitude 为 <code>0.45</code>、angular speed 为 <code>1</code>、joint amplitude 为 <code>1</code>。Start HTTP 为每项接受 <code>0</code> 到 <code>10</code> 的有限值。这些数学轨迹不计算物理接触。</p><p>继续<a href="./spatial-workbench">空间工作台</a>。生产 Newton、持久 Recording、远程入口和机器人任务仍是独立工作。</p><hr><p>源码版本：<code>c80e63c8c063</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/c80e63c8c063e44ca80c85970b518c35fb448c8e/docs/tutorials/simulation-session.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,35)])])}const g=a(t,[["render",p]]);export{k as __pageData,g as default};
